mapper.insert:
insert into vm_emergency_user_lnglat_info (user_id,industry_code, app_ver_code,
                                           longitude, latitude, take_point_time,tenant_id
) values (#{userId},#{industryCode},#{appVerCode},#{longitude},#{latitude},#{takePointTime},#{tenantId})

mapper.update:
update vm_emergency_user_lnglat_info
set longitude       = #{longitude},
    latitude        = #{latitude},
    take_point_time = #{takePointTime}
where user_id = #{userId}
  and industry_code = #{industryCode}
  and tenant_id = #{tenantId}

UPDATE vm_emergency_user
SET user_id = #{userId},
    modifier = #{modifier},
    update_time = now()
WHERE emergency_dept_id = #{emergencyDeptId}
  and tenant_id = #{tenantId}
  and industry_code = #{industryCode}

mapper.delete:
update vm_emergency_user
set delete_flag = 1,
modifier = #{modifier},
update_time = now()
where emergency_dept_id = #{emergencyDeptId}
and tenant_id = #{tenantId}
and industry_code = #{industryCode}

    and user_id = #{userId}

mapper.select:
select count(user_id)
from vm_emergency_user_lnglat_info
where user_id = #{userId}
and industry_code = #{industryCode}

    and tenant_id = #{tenantId}

select distinct u.NICK_NAME as nickName, u.USER_NAME as userName, u.SEX as sex, veuli.user_id, longitude, latitude, take_point_time, IF(PHONENUMBER, CONCAT(SUBSTRING(PHONENUMBER, 1, 3), '****', SUBSTRING(PHONENUMBER, 8)), NULL) AS phoneNumber, u.remark as remark, (case when TIMESTAMPDIFF(MINUTE, take_point_time, now()) < 5 then '1' else '0' end) as is_line, vfc.mobile_terminal_num, vfc.dispatch_desk_num from vm_emergency_user_lnglat_info veuli left join vm_fusion_communication_t vfc on veuli.USER_ID = vfc.user_id left join sys_user u on veuli.USER_ID = u.user_id JOIN (WITH RECURSIVE cte AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50) SELECT u.user_id, SUBSTRING_INDEX(SUBSTRING_INDEX(u.dept_id, ',', n), ',', -1) AS dept_id FROM sys_user u JOIN cte ON cte.n <= LENGTH(u.dept_id) - LENGTH(REPLACE(u.dept_id, ',', '')) + 1 WHERE u.del_flag = '0') ud ON u.user_id = ud.user_id LEFT JOIN sys_dept d ON ud.dept_id = d.dept_id and d.del_flag = '0' left join sys_industry_conf ic on ic.industry_code = d.INDUSTRY_CODE and ic.delete_flag = '0' where u.DEL_FLAG = '0' ${dataScope}
AND veuli.longitude = #{longitude}
AND veuli.latitude = #{latitude}

select * from vm_emergency_user WHERE delete_flag = '0'
and emergency_dept_id in

    #{deptId}
